using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using VirtualCompany.Domain.Entities;using VirtualCompany.Domain.Enums;
namespace VirtualCompany.Infrastructure.Persistence;
internal sealed class SalesPresentationRunArtifactConfiguration:IEntityTypeConfiguration<SalesPresentationRunArtifact>{public void Configure(EntityTypeBuilder<SalesPresentationRunArtifact>b){b.ToTable("sales_presentation_run_artifacts",t=>t.HasCheckConstraint("CK_sales_presentation_run_artifacts_order","preparation_version >= 1 AND artifact_order >= 0"));b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.Property(x=>x.RunId).HasColumnName("run_id");b.Property(x=>x.PreparationVersion).HasColumnName("preparation_version");b.Property(x=>x.Type).HasColumnName("artifact_type").HasConversion(x=>x.ToStorageValue(),x=>SalesPresentationPresetEnumValues.ParseRunArtifactType(x)).HasMaxLength(32);b.Property(x=>x.Content).HasColumnName("content").HasMaxLength(4000);b.Property(x=>x.Classification).HasColumnName("classification").HasMaxLength(32);b.Property(x=>x.SourceReference).HasColumnName("source_reference").HasMaxLength(500);b.Property(x=>x.PresetSlideId).HasColumnName("preset_slide_id");b.Property(x=>x.Order).HasColumnName("artifact_order");b.Property(x=>x.AiRunId).HasColumnName("ai_run_id");b.Property(x=>x.CreatedUtc).HasColumnName("created_at");b.HasIndex(x=>new{x.CompanyId,x.RunId,x.PreparationVersion,x.Type,x.Order});b.HasOne(x=>x.Run).WithMany(x=>x.Artifacts).HasForeignKey(nameof(SalesPresentationRunArtifact.CompanyId),nameof(SalesPresentationRunArtifact.RunId)).HasPrincipalKey(nameof(SalesPresentationRun.CompanyId),nameof(SalesPresentationRun.Id)).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.PresetSlide).WithMany().HasForeignKey(nameof(SalesPresentationRunArtifact.CompanyId),nameof(SalesPresentationRunArtifact.PresetSlideId)).HasPrincipalKey(nameof(SalesPresentationPresetSlide.CompanyId),nameof(SalesPresentationPresetSlide.Id)).OnDelete(DeleteBehavior.Restrict);}}
